//! Configuration parsing and data structures for postmaster.
//!
//! The config is generated by the Nix module as JSON. It contains only
//! public information (store paths for ciphertext + key *names*).

#![allow(missing_docs, missing_debug_implementations)]

use std::collections::HashMap;
use std::path::{Component, Path, PathBuf};

use serde::Deserialize;

use crate::adapter::KeyNaming;

/// Full configuration loaded from the JSON file produced by the Nix module.
#[derive(Deserialize, Debug)]
pub struct Config {
    /// Where the .env.keys material comes from.
    pub keys: KeysSource,
    /// Absolute socket path → what to serve on it.
    pub credentials: HashMap<PathBuf, Entry>,
}

#[derive(Deserialize, Debug)]
#[serde(rename_all = "snake_case")]
/// Where postmaster should obtain its own private keys.
pub enum KeysSource {
    /// Name under $CREDENTIALS_DIRECTORY (the daemon's own LoadCredential).
    Credential(String),
    /// Absolute filesystem path (must not live in the Nix store).
    File(PathBuf),
}

#[derive(Deserialize, Clone, Debug)]
/// A single credential mapping served by postmaster.
pub struct Entry {
    /// encrypted env file (a Nix store path; ciphertext is public).
    pub env_file: PathBuf,
    /// Which key inside it to serve.
    pub key: String,
    /// Additionally allow this (non-root) user to fetch the credential.
    /// Used by the darwin module, where consumers are launchd daemons
    /// connecting as their own service user rather than pid 1.
    #[serde(default)]
    pub peer_user: Option<String>,
}

#[derive(Debug)]
pub struct Args {
    pub config: PathBuf,
    pub bind: bool,
    pub allow_nonroot: bool,
}

#[derive(Debug)]
pub enum Invocation {
    Serve(Args),
    Fetch(PathBuf),
    /// `postmaster exec --config <exec.json> [--check] [--verify-keys]`
    /// `-- <argv…>`: decrypt + inject per the launcher contract, then
    /// execvp argv. See launcher.rs.
    Exec {
        config: PathBuf,
        check: bool,
        /// Preflight: attempt a test decryption of one encrypted value
        /// from each env file before proceeding to exec. Catches stale
        /// keys from a previous rotation cycle that are valid hex but
        /// no longer match the ciphertext (audit finding #4).
        verify_keys: bool,
        argv: Vec<String>,
    },
    /// `postmaster setup --config <exec.json> [--recheck] [--unattended]
    /// [--force] [--keys-dir <path>]`: verify platform prerequisites,
    /// create keys directory with correct permissions, optionally seed
    /// keychain items, and validate the environment. Idempotent — skips
    /// steps that are already correct. `--recheck` re-verifies without
    /// creating or modifying anything.
    Setup {
        config: PathBuf,
        recheck: bool,
        unattended: bool,
        force: bool,
        keys_dir: Option<PathBuf>,
    },
    /// `postmaster cleanup --config <exec.json>`: remove all secret files
    /// from the secrets_dir configured in the exec config. Intended for
    /// `ExecStopPost` in systemd or equivalent lifecycle hooks in other
    /// service managers. Does not decrypt — only removes files that
    /// postmaster would have written.
    Cleanup {
        config: PathBuf,
    },
    /// Print help text and exit successfully.
    Help(Option<String>),
    /// Print version and exit successfully.
    Version,
}

pub const VERSION: &str = env!("CARGO_PKG_VERSION");

