/// Parse command line arguments. Kept simple with no external deps.
pub fn parse_args() -> Result<Invocation, String> {
    parse_args_from(std::env::args().skip(1))
}

pub fn parse_args_from(args: impl IntoIterator<Item = String>) -> Result<Invocation, String> {
    let mut it = args.into_iter().peekable();

    // No args: print help and fail
    if it.peek().is_none() {
        return Err(format!(
            "{HELP_TOP}\n\nerror: no subcommand or --config provided"
        ));
    }

    match it.peek().map(String::as_str) {
        // Global flags that work before any subcommand
        Some("--help") | Some("-h") => {
            it.next();
            if it.next().is_some() {
                return Err("error: --help does not take arguments".into());
            }
            Ok(Invocation::Help(None))
        }
        Some("--version") | Some("-V") => {
            it.next();
            if it.next().is_some() {
                return Err("error: --version does not take arguments".into());
            }
            Ok(Invocation::Version)
        }
        Some("help") => {
            it.next();
            let sub = it.next();
            if it.next().is_some() {
                return Err(
                    "error: `help` takes at most one argument (the subcommand name)".into(),
                );
            }
            Ok(Invocation::Help(sub))
        }
        Some("fetch") => {
            it.next();
            let path = it.next().ok_or("error: fetch requires a socket path")?;
            if it.next().is_some() {
                return Err("error: fetch takes exactly one argument (the socket path)".into());
            }
            Ok(Invocation::Fetch(PathBuf::from(path)))
        }
        Some("exec") => {
            it.next();
            let mut config = None;
            let mut check = false;
            let mut verify_keys = false;
            let mut argv: Vec<String> = Vec::new();
            while let Some(a) = it.next() {
                match a.as_str() {
                    "--config" => {
                        config = Some(PathBuf::from(
                            it.next().ok_or("error: --config requires a path")?,
                        ));
                    }
                    "--check" => check = true,
                    "--verify-keys" => verify_keys = true,
                    "--help" | "-h" => return Ok(Invocation::Help(Some("exec".into()))),
                    "--" => {
                        argv = it.collect();
                        break;
                    }
                    other => {
                        return Err(format!(
                            "error: exec: unknown option `{other}`\n\n{HELP_EXEC}"
                        ));
                    }
                }
            }
            if check {
                if !argv.is_empty() {
                    return Err("error: exec --check does not accept a command after `--`".into());
                }
            } else if argv.is_empty() {
                return Err(format!(
                    "error: exec: missing command after `--`\n\n{HELP_EXEC}"
                ));
            }
            Ok(Invocation::Exec {
                config: config.ok_or("error: exec: missing required --config <exec.json>")?,
                check,
                verify_keys,
                argv,
            })
        }
        Some("setup") => {
            it.next();
            let mut config = None;
            let mut recheck = false;
            let mut unattended = false;
            let mut force = false;
            let mut keys_dir = None;
            while let Some(a) = it.next() {
                match a.as_str() {
                    "--config" => {
                        config = Some(PathBuf::from(
                            it.next().ok_or("error: --config requires a path")?,
                        ));
                    }
                    "--recheck" => recheck = true,
                    "--unattended" | "--non-interactive" => unattended = true,
                    "--force" => force = true,
                    "--keys-dir" => {
                        keys_dir = Some(PathBuf::from(
                            it.next().ok_or("error: --keys-dir requires a path")?,
                        ));
                    }
                    "--help" | "-h" => return Ok(Invocation::Help(Some("setup".into()))),
                    other => {
                        return Err(format!(
                            "error: setup: unknown option `{other}`\n\n{HELP_SETUP}"
                        ));
                    }
                }
            }
            let config = config.ok_or("error: setup: missing required --config <exec.json>")?;
            Ok(Invocation::Setup {
                config,
                recheck,
                unattended,
                force,
                keys_dir,
            })
        }
        Some("cleanup") => {
            it.next();
            let mut config = None;
            while let Some(a) = it.next() {
                match a.as_str() {
                    "--config" => {
                        config = Some(PathBuf::from(
                            it.next().ok_or("error: --config requires a path")?,
                        ));
                    }
                    "--help" | "-h" => return Ok(Invocation::Help(Some("cleanup".into()))),
                    other => {
                        return Err(format!(
                            "error: cleanup: unknown option `{other}`\n\n{HELP_CLEANUP}"
                        ));
                    }
                }
            }
            Ok(Invocation::Cleanup {
                config: config.ok_or("error: cleanup: missing required --config <exec.json>")?,
            })
        }
        // Serve mode (default, no subcommand keyword)
        Some("--config") | Some("--bind") | Some("--allow-nonroot") => {
            let mut config = None;
            let mut bind = false;
            let mut allow_nonroot = false;
            while let Some(a) = it.next() {
                match a.as_str() {
                    "--config" => {
                        config = Some(PathBuf::from(
                            it.next().ok_or("error: --config requires a path")?,
                        ));
                    }
                    "--bind" => bind = true,
                    "--allow-nonroot" => allow_nonroot = true,
                    "--help" | "-h" => return Ok(Invocation::Help(None)),
                    other => {
                        return Err(format!("error: unknown option `{other}`\n\n{HELP_TOP}"));
                    }
                }
            }
            Ok(Invocation::Serve(Args {
                config: config.ok_or("error: missing required --config <file.json>")?,
                bind,
                allow_nonroot,
            }))
        }
        Some(other) => Err(format!(
            "error: unknown subcommand `{other}`\n\nTry `postmaster help` for usage.\n"
        )),
        None => unreachable!("empty args handled above"),
    }
}

/// Launcher configuration for `postmaster exec` — THE cross-binding
/// contract. Generated by the Nix module (later: other bindings); contains
/// only public data: store paths of ciphertext, key *names*, socket paths.
#[derive(Deserialize, Debug)]
#[serde(deny_unknown_fields)]
pub struct ExecConfig {
    pub mode: ExecMode,
    /// Ordered key sources; see launcher::load_ring for selection rules.
    #[serde(default)]
    pub keys: Vec<KeySourceSpec>,
    /// Encrypted env files, in precedence order (first wins unless overload).
    #[serde(default)]
    pub env_files: Vec<PathBuf>,
    /// Encrypted `postmaster_bundle` files, in precedence order.
    /// Each file is a JSON container with `format: "postmaster.bundle"`.
    /// Entries are merged with `env_files` entries; bundle keys use the
    /// same identifier rule and the same injection modes.
    #[serde(default)]
    pub bundle_files: Vec<PathBuf>,
    /// Any undecryptable value aborts before exec (fail closed).
    #[serde(default = "default_true")]
    pub strict: bool,
    /// File values override process env; later files override earlier.
    #[serde(default)]
    pub overload: bool,
    /// files/credentials(darwin) mode: where plaintext files land.
    #[serde(default)]
    pub secrets_dir: Option<PathBuf>,
    /// files mode: keys ALSO exported as real env vars.
    #[serde(default)]
    pub passthrough: Vec<String>,
    /// credentials mode: keys exposed as $CREDENTIALS_DIRECTORY/<KEY>.
    #[serde(default)]
    pub credential_keys: Vec<String>,
    /// credentials mode, darwin: key → postmaster socket to fetch from.
    /// Non-empty selects the fetch path; empty means systemd already
    /// materialized the credentials.
    #[serde(default)]
    pub sockets: HashMap<String, PathBuf>,
    /// darwin: refuse to write plaintext unless this mount point is the
    /// HFS ramdisk and secrets_dir is a directory we own.
    #[serde(default)]
    pub verify_ramdisk: Option<PathBuf>,
}

#[derive(Deserialize, Debug, Clone, Copy, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ExecMode {
    Env,
    Files,
    Credentials,
}

/// Where the launcher's private keys come from. Selection contract:
/// `credential` is skippable (absent $CREDENTIALS_DIRECTORY or file ⇒ try
/// the next source); `file`/`keychain`/`environment` are terminal — once
/// reached, their failure is the launcher's failure (fail closed).
#[derive(Deserialize, Debug, Clone)]
#[serde(rename_all = "snake_case")]
pub enum KeySourceSpec {
    Credential(String),
    File(PathBuf),
    Keychain(String),
    Environment,
}

impl ExecConfig {
    /// Validate the public shape of an exec config without touching local
    /// secret material, decrypting values, probing sockets, or inspecting the
    /// host filesystem. This is the parser-authoritative `--check` contract
    /// automation bindings can run in CI before deployment.
    pub fn validate_shape(&self) -> Result<(), String> {
        validate_key_sources(&self.keys)?;
        validate_ident_list("passthrough", &self.passthrough)?;
        validate_mode_irrelevant_fields(self)?;
        validate_mode_required_fields(self)?;
        Ok(())
    }
}

fn validate_mode_required_fields(cfg: &ExecConfig) -> Result<(), String> {
    match cfg.mode {
        ExecMode::Env => {
            validate_decrypting_mode(cfg, "env")?;
        }
        ExecMode::Files => {
            validate_decrypting_mode(cfg, "files")?;
            if cfg.secrets_dir.is_none() {
                return Err("files mode requires secrets_dir".into());
            }
        }
        ExecMode::Credentials => {
            if cfg.credential_keys.is_empty() {
                return Err("credentials mode requires credential_keys".into());
            }
            validate_ident_list("credential_keys", &cfg.credential_keys)?;
            if !cfg.sockets.is_empty() {
                if cfg.secrets_dir.is_none() {
                    return Err("credentials(fetch) mode requires secrets_dir".into());
                }
                for key in &cfg.credential_keys {
                    if !cfg.sockets.contains_key(key) {
                        return Err(format!("{key}: no socket mapped in exec config"));
                    }
                }
            }
        }
    }
    Ok(())
}

/// Reject fields that are irrelevant to the selected mode. This catches
/// binding bugs early — before any secret material transits — so a config
/// generator that accidentally includes `env_files` in a credentials-mode
/// config or `credential_keys` in an env-mode config fails at `--check`
/// rather than silently ignoring the stray field. Default/empty values
/// (empty vecs, `None`, `false`) are accepted since serde fills them in
/// even when the generator omits the field entirely.
fn validate_mode_irrelevant_fields(cfg: &ExecConfig) -> Result<(), String> {
    match cfg.mode {
        ExecMode::Env => {
            if cfg.secrets_dir.is_some() {
                return Err("env mode does not use secrets_dir".into());
            }
            if !cfg.credential_keys.is_empty() {
                return Err("env mode does not use credential_keys".into());
            }
            if !cfg.sockets.is_empty() {
                return Err("env mode does not use sockets".into());
            }
            if cfg.verify_ramdisk.is_some() {
                return Err("env mode does not use verify_ramdisk".into());
            }
            if !cfg.passthrough.is_empty() {
                return Err("env mode does not use passthrough".into());
            }
        }
        ExecMode::Files => {
            if !cfg.credential_keys.is_empty() {
                return Err("files mode does not use credential_keys".into());
            }
            if !cfg.sockets.is_empty() {
                return Err("files mode does not use sockets".into());
            }
        }
        ExecMode::Credentials => {
            if !cfg.keys.is_empty() {
                return Err(
                    "credentials mode does not use keys (key material lives on the daemon)".into(),
                );
            }
            if !cfg.env_files.is_empty() {
                return Err(
                    "credentials mode does not use env_files (ciphertext lives on the daemon)"
                        .into(),
                );
            }
            if !cfg.bundle_files.is_empty() {
                return Err(
                    "credentials mode does not use bundle_files (ciphertext lives on the daemon)"
                        .into(),
                );
            }
            if cfg.overload {
                return Err("credentials mode does not use overload".into());
            }
            if !cfg.passthrough.is_empty() {
                return Err("credentials mode does not use passthrough".into());
            }
        }
    }
    Ok(())
}

fn validate_decrypting_mode(cfg: &ExecConfig, mode: &str) -> Result<(), String> {
    if cfg.env_files.is_empty() && cfg.bundle_files.is_empty() {
        return Err(format!(
            "{mode} mode requires env_files or bundle_files (at least one non-empty)"
        ));
    }
    if cfg.keys.is_empty() {
        return Err(format!("{mode} mode requires keys"));
    }
    for path in &cfg.env_files {
        KeyNaming::Env.key_var_for(path)?;
    }
    Ok(())
}

fn validate_key_sources(specs: &[KeySourceSpec]) -> Result<(), String> {
    for spec in specs {
        match spec {
            KeySourceSpec::Credential(name) => validate_credential_source_name(name)?,
            KeySourceSpec::File(path) if path.starts_with("/nix/store") => {
                return Err(format!(
                    "{}: refusing plaintext private keys from the world-readable Nix store",
                    path.display()
                ));
            }
            _ => {}
        }
    }
    Ok(())
}

fn validate_credential_source_name(name: &str) -> Result<(), String> {
    if name.contains('\0') {
        return Err(format!(
            "credential source {name:?}: contains NUL byte (not a valid path component)"
        ));
    }
    let mut components = Path::new(name).components();
    match (components.next(), components.next()) {
        (Some(Component::Normal(_)), None) => Ok(()),
        _ => Err(format!(
            "credential source {name:?}: must be a single relative path component"
        )),
    }
}

fn validate_ident_list(field: &str, keys: &[String]) -> Result<(), String> {
    for key in keys {
        if !crate::keys::is_ident(key) {
            return Err(format!("{field} entry {key:?}: not a valid identifier"));
        }
    }
    Ok(())
}

fn default_true() -> bool {
    true
}

#[cfg(test)]
#[allow(unused_qualifications, clippy::panic, clippy::unwrap_used)]
mod tests {
    use super::*;

    fn parse(v: &[&str]) -> Result<Invocation, String> {
        parse_args_from(v.iter().map(ToString::to_string))
    }

    #[test]
    fn parse_exec() {
        match parse(&[
            "exec", "--config", "/e.json", "--", "/bin/app", "--flag", "x",
        ]) {
            Ok(Invocation::Exec {
                config,
                check,
                verify_keys,
                argv,
            }) => {
                assert_eq!(config, PathBuf::from("/e.json"));
                assert!(!check);
                assert!(!verify_keys);
                assert_eq!(argv, vec!["/bin/app", "--flag", "x"]);
            }
            other => panic!("expected Exec, got {other:?}"),
        }
    }

    #[test]
    fn parse_exec_check() {
        match parse(&["exec", "--config", "/e.json", "--check"]) {
            Ok(Invocation::Exec {
                config,
                check,
                argv,
                ..
            }) => {
                assert_eq!(config, PathBuf::from("/e.json"));
                assert!(check);
                assert!(argv.is_empty());
            }
            other => panic!("expected Exec check, got {other:?}"),
        }
    }

    #[test]
    fn parse_exec_verify_keys() {
        match parse(&[
            "exec",
            "--config",
            "/e.json",
            "--verify-keys",
            "--",
            "/bin/app",
        ]) {
            Ok(Invocation::Exec {
                config,
                check,
                verify_keys,
                argv,
            }) => {
                assert_eq!(config, PathBuf::from("/e.json"));
                assert!(!check);
                assert!(verify_keys);
                assert_eq!(argv, vec!["/bin/app"]);
            }
            other => panic!("expected Exec with --verify-keys, got {other:?}"),
        }
    }

    #[test]
    fn parse_exec_requires_command() {
        assert!(parse(&["exec", "--config", "/e.json"]).is_err());
        assert!(parse(&["exec", "--config", "/e.json", "--"]).is_err());
        assert!(parse(&["exec", "--config", "/e.json", "--check", "--", "/bin/app"]).is_err());
    }

    #[test]
    fn parse_fetch_and_serve_still_work() {
        assert!(matches!(
            parse(&["fetch", "/s.sock"]),
            Ok(Invocation::Fetch(_))
        ));
        assert!(matches!(
            parse(&["--config", "/c.json", "--bind"]),
            Ok(Invocation::Serve(Args { bind: true, .. }))
        ));
    }

    #[test]
    fn parse_help_top_level() {
        assert!(matches!(parse(&["--help"]), Ok(Invocation::Help(None))));
        assert!(matches!(parse(&["-h"]), Ok(Invocation::Help(None))));
    }

    #[test]
    fn parse_help_subcommand() {
        assert!(matches!(parse(&["help"]), Ok(Invocation::Help(None))));
        assert!(matches!(
            parse(&["help", "exec"]),
            Ok(Invocation::Help(Some(s))) if s == "exec"
        ));
        assert!(matches!(
            parse(&["help", "setup"]),
            Ok(Invocation::Help(Some(s))) if s == "setup"
        ));
    }

    #[test]
    fn parse_version() {
        assert!(matches!(parse(&["--version"]), Ok(Invocation::Version)));
        assert!(matches!(parse(&["-V"]), Ok(Invocation::Version)));
    }

    #[test]
    fn parse_no_args_fails() {
        assert!(parse(&[]).is_err());
    }

    #[test]
    fn parse_unknown_subcommand_fails() {
        let err = parse(&["bogus"]).unwrap_err();
        assert!(err.contains("unknown subcommand"), "{err}");
        assert!(err.contains("Try `postmaster help`"), "{err}");
    }

    #[test]
    fn parse_help_in_exec_subcommand() {
        assert!(matches!(
            parse(&["exec", "--help"]),
            Ok(Invocation::Help(Some(s))) if s == "exec"
        ));
    }

    #[test]
    fn parse_help_in_setup_subcommand() {
        assert!(matches!(
            parse(&["setup", "--help"]),
            Ok(Invocation::Help(Some(s))) if s == "setup"
        ));
    }

    #[test]
    fn parse_setup_flags() {
        assert!(matches!(
            parse(&["setup", "--config", "/e.json", "--recheck"]),
            Ok(Invocation::Setup { recheck: true, .. })
        ));
        assert!(matches!(
            parse(&["setup", "--config", "/e.json", "--unattended"]),
            Ok(Invocation::Setup {
                unattended: true,
                ..
            })
        ));
        assert!(matches!(
            parse(&["setup", "--config", "/e.json", "--force"]),
            Ok(Invocation::Setup { force: true, .. })
        ));
        assert!(matches!(
            parse(&["setup", "--config", "/e.json", "--keys-dir", "/custom"]),
            Ok(Invocation::Setup { keys_dir: Some(p), .. }) if &*p == std::path::Path::new("/custom")
        ));
    }

    #[test]
    fn parse_cleanup() {
        assert!(matches!(
            parse(&["cleanup", "--config", "/e.json"]),
            Ok(Invocation::Cleanup { config }) if &*config == std::path::Path::new("/e.json")
        ));
        assert!(parse(&["cleanup"]).is_err());
        assert!(parse(&["cleanup", "--config"]).is_err());
    }

    #[test]
    fn parse_help_in_cleanup_subcommand() {
        assert!(matches!(
            parse(&["cleanup", "--help"]),
            Ok(Invocation::Help(Some(s))) if s == "cleanup"
        ));
    }

    #[test]
    fn key_var_for_edge_cases() {
        assert!(
            KeyNaming::Env
                .key_var_for(std::path::Path::new("no-dot-env"))
                .is_err()
        );
    }

    #[test]
    fn exec_config_parses() {
        let json = r#"{
      "mode": "files",
      "keys": [{"credential": "postmaster-myapp"}, "environment"],
      "env_files": ["/nix/store/x/.env.production"],
      "strict": true,
      "overload": false,
      "secrets_dir": "/run/postmaster",
      "passthrough": ["RUST_LOG"]
    }"#;
        let c: ExecConfig = serde_json::from_str(json).unwrap();
        assert!(matches!(c.mode, ExecMode::Files));
        assert_eq!(c.keys.len(), 2);
        assert!(matches!(c.keys[1], KeySourceSpec::Environment));
        assert!(c.strict && !c.overload);
        assert!(c.sockets.is_empty() && c.verify_ramdisk.is_none());
    }

    #[test]
    fn exec_config_minimal_credentials() {
        let json = r#"{"mode":"credentials","credential_keys":["DB_URL"]}"#;
        let c: ExecConfig = serde_json::from_str(json).unwrap();
        assert!(matches!(c.mode, ExecMode::Credentials));
        assert!(c.strict, "strict must default to true");
        assert_eq!(c.credential_keys, vec!["DB_URL"]);
        c.validate_shape().unwrap();
    }

    #[test]
    fn exec_config_rejects_unknown_fields() {
        let json = r#"{"mode":"credentials","credential_keys":["DB_URL"],"adapter":"dotenvx"}"#;
        let err = serde_json::from_str::<ExecConfig>(json).unwrap_err();
        assert!(
            err.to_string().contains("unknown field"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn exec_config_validate_shape_catches_mode_requirements() {
        let files_missing_dir: ExecConfig = serde_json::from_str(
            r#"{"mode":"files","keys":["environment"],"env_files":["/nix/store/x/.env"]}"#,
        )
        .unwrap();
        assert!(
            files_missing_dir
                .validate_shape()
                .unwrap_err()
                .contains("secrets_dir")
        );

        let invalid_credential_key: ExecConfig =
            serde_json::from_str(r#"{"mode":"credentials","credential_keys":["../DB_URL"]}"#)
                .unwrap();
        assert!(
            invalid_credential_key
                .validate_shape()
                .unwrap_err()
                .contains("identifier")
        );

        let store_key: ExecConfig = serde_json::from_str(
            r#"{"mode":"env","keys":[{"file":"/nix/store/abc/.env.keys"}],"env_files":["/nix/store/x/.env"]}"#,
        )
        .unwrap();
        assert!(
            store_key
                .validate_shape()
                .unwrap_err()
                .contains("Nix store")
        );
    }

    #[test]
    fn validate_shape_rejects_mode_irrelevant_fields() {
        // env mode should reject secrets_dir, credential_keys, sockets,
        // verify_ramdisk, and passthrough.
        let env_with_secrets_dir: ExecConfig = serde_json::from_str(
            r#"{"mode":"env","keys":["environment"],"env_files":["/nix/store/x/.env"],"secrets_dir":"/run/x"}"#,
        )
        .unwrap();
        assert!(
            env_with_secrets_dir
                .validate_shape()
                .unwrap_err()
                .contains("env mode does not use secrets_dir")
        );

        let env_with_credential_keys: ExecConfig = serde_json::from_str(
            r#"{"mode":"env","keys":["environment"],"env_files":["/nix/store/x/.env"],"credential_keys":["DB"]}"#,
        )
        .unwrap();
        assert!(
            env_with_credential_keys
                .validate_shape()
                .unwrap_err()
                .contains("env mode does not use credential_keys")
        );

        // files mode should reject credential_keys and sockets.
        let files_with_sockets: ExecConfig = serde_json::from_str(
            r#"{"mode":"files","keys":["environment"],"env_files":["/nix/store/x/.env"],"secrets_dir":"/run/x","sockets":{"DB":"/s.sock"}}"#,
        )
        .unwrap();
        assert!(
            files_with_sockets
                .validate_shape()
                .unwrap_err()
                .contains("files mode does not use sockets")
        );

        // credentials mode should reject keys, env_files, overload, passthrough.
        let creds_with_env_files: ExecConfig = serde_json::from_str(
            r#"{"mode":"credentials","credential_keys":["DB"],"env_files":["/nix/store/x/.env"]}"#,
        )
        .unwrap();
        assert!(
            creds_with_env_files
                .validate_shape()
                .unwrap_err()
                .contains("credentials mode does not use env_files")
        );

        let creds_with_overload: ExecConfig = serde_json::from_str(
            r#"{"mode":"credentials","credential_keys":["DB"],"overload":true}"#,
        )
        .unwrap();
        assert!(
            creds_with_overload
                .validate_shape()
                .unwrap_err()
                .contains("credentials mode does not use overload")
        );
    }
}
